              <input type="text" placeholder="Cor do Veículo" className="w-full bg-dark/50 p-4 rounded-xl border border-white/10 text-xs font-bold" value={formColor} onChange={(e) => setFormColor(e.target.value)} required />
              <button type="submit" disabled={isLoading} className="w-full py-5 bg-accent text-white font-black uppercase text-xs tracking-[0.2em] rounded-2xl shadow-lg mt-4 disabled:opacity-50">
                {isLoading ? "Processando..." : "Confirmar Agendamento"}
              </button>
            </form>
          </div>
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
}

