    <ChevronRight size={16} className="absolute right-6 opacity-30 group-hover:opacity-100 group-hover:translate-x-1 transition-all" />
  </button>
);

const FullscreenOverlay = ({ title, isOpen, onClose, children }: { title: string, isOpen: boolean, onClose: () => void, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[100] bg-dark/95 backdrop-blur-2xl flex flex-col animate-slide-in">
      <div className="flex items-center justify-between p-6 border-b border-white/5">
        <button onClick={onClose} className="p-2 glass rounded-xl text-white hover:bg-accent transition-colors">
          <ArrowLeft size={20} />
        </button>
        <h2 className="text-lg font-display font-black uppercase tracking-widest text-accent italic">{title}</h2>
        <div className="w-10"></div>
      </div>
      <div className="flex-1 overflow-y-auto custom-scrollbar p-6">
        {children}
      </div>
    </div>
  );
};

const Toast = ({ message, type = 'success', onClose }: { message: string, type?: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`fixed bottom-24 left-1/2 -translate-x-1/2 z-[200] px-6 py-4 rounded-2xl glass border-l-4 ${type === 'success' ? 'border-green-500' : 'border-red-500'} flex items-center gap-3 animate-fade-up shadow-2xl`}>
      {type === 'success' ? <CheckCircle className="text-green-500" /> : <AlertCircle className="text-red-500" />}
      <span className="text-sm font-bold tracking-tight">{message}</span>
    </div>
  );
};

