    <p className="text-xs text-gray-500 leading-relaxed font-medium">{description}</p>
  </div>
);

const ActionCard = ({ title, icon: Icon, onClick }: { title: string, icon: any, onClick: () => void }) => (
  <button 
    onClick={(e) => {
      e.preventDefault();
      onClick();
    }}
    className="group relative w-full glass p-6 rounded-3xl flex flex-col items-center justify-center gap-4 transition-all hover:scale-[1.02] hover:border-accent active:scale-95 animate-fade-up outline-none"
  >
