      id: Date.now(),
      servico: activeModal!.name,
      data: format(parseISO(formDate), 'dd/MM/yyyy'),
      horario: formTime,
      nome: formName,
      telefone: formPhone,
      veiculo: formVehicle,
      cor: formColor,
      obs: formObs || 'Nenhuma',
      status: 'pendente'
    };

