  Calendar, Clock, Car, MapPin, Phone, Instagram, Shield, Sparkles, 
  Droplets, Zap, ShieldCheck, Gem, Sun, Layers, Star, UserCheck, 
  Cpu, X, ChevronRight, CheckCircle, AlertCircle, Info, Play
} from 'lucide-react';
