  const [formColor, setFormColor] = useState('');
  const [formObs, setFormObs] = useState('');

  // Fetch CMS Data and Log Visit
  useEffect(() => {
    const fetchData = async () => {
      try {
        // Log Visit
        const analyticsRef = doc(db, "analytics", "stats");
        try {
          await updateDoc(analyticsRef, { visits: increment(1) });
        } catch (e) {
          // If doc doesn't exist yet
          await setDoc(analyticsRef, { visits: 1 }, { merge: true });
        }

        // Fetch Content
        const contentRef = doc(db, "site_content", "main");
        const docSnap = await getDoc(contentRef);
        if (docSnap.exists()) {
          const data = docSnap.data();
          if (data.reels) setReels(data.reels);
          if (data.products) setProducts(data.products);
        }
      } catch (error) {
        console.log("Using default data (offline or config issue)");
      }
    };
    fetchData();
  }, []);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 80;
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  const handleBookingSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formTime || !formName || !formPhone || !formVehicle) {
      setToast({ message: 'Preencha todos os campos obrigatórios!', type: 'error' });
      return;
    }

    setIsLoading(true);

    const newBooking: Booking = {
      id: Date.now(),
      servico: activeModal!.name,
      data: format(parseISO(formDate), 'dd/MM/yyyy'),
      horario: formTime,
      nome: formName,
      telefone: formPhone,
      veiculo: formVehicle,
      cor: formColor,
      obs: formObs || 'Nenhuma',
      status: 'pendente'
    };

    setTimeout(() => {
      setIsLoading(false);
      setToast({ message: 'Redirecionando para o WhatsApp...', type: 'success' });

      const message = `Olá, EXTREME STÉTICA! 🚗\nGostaria de agendar o serviço:\n📋 Serviço: ${newBooking.servico}\n📅 Data: ${newBooking.data}\n🕐 Horário: ${newBooking.horario}\n👤 Cliente:\nNome: ${newBooking.nome}\nTelefone: ${newBooking.telefone}\nVeículo: ${newBooking.veiculo} - ${newBooking.cor}\n💬 Observações: ${newBooking.obs}\nAguardo confirmação!`;

      const encoded = encodeURIComponent(message);
      window.open(`https://wa.me/5573988176142?text=${encoded}`, '_blank');

      setActiveModal(null);
      resetForm();
    }, 1500);
  };

  const resetForm = () => {
    setFormDate(format(startOfToday(), 'yyyy-MM-dd'));
    setFormTime('');
    setFormName('');
    setFormPhone('');
    setFormVehicle('');
    setFormColor('');
    setFormObs('');
  };

  const getIcon = (name: string) => {
    switch (name) {
      case 'Droplets': return Droplets;
      case 'Car': return Car;
      case 'Sparkle': return Sparkles;
      case 'Zap': return Zap;
      case 'ShieldCheck': return ShieldCheck;
      case 'Gem': return Gem;
      case 'Sun': return Sun;
      case 'Layers': return Layers;
      case 'Star': return Star;
      case 'UserCheck': return UserCheck;
      case 'Shield': return Shield;
      case 'Cpu': return Cpu;
      default: return Info;
    }
  };

  const formatPhone = (value: string) => {
    const numbers = value.replace(/\D/g, '');
    if (numbers.length <= 11) {
      return numbers
        .replace(/^(\d{2})(\d)/g, '($1) $2')
        .replace(/(\d)(\d{4})$/, '$1-$2');
    }
    return value;
  };

  return (
