                          onChange={(e) => {
                            const newProds = [...cmsProducts];
                            newProds[idx].description = e.target.value;
                            setCmsProducts(newProds);
                          }}
                        />
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

          </div>
        )}
      </main>
    </div>
  );
}

