const Toast = ({ message, type = 'success', onClose }: { message: string, type?: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`fixed bottom-24 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 rounded-xl glass border-l-4 ${type === 'success' ? 'border-green-500' : 'border-red-500'} flex items-center gap-3 animate-fade-up shadow-2xl`}>
      {type === 'success' ? <CheckCircle className="text-green-500" /> : <AlertCircle className="text-red-500" />}
      <span className="text-sm font-medium">{message}</span>
    </div>
  );
};

interface ReelCardProps {
  url: string;
  index: number;
  playingIndex: number | null;
  setPlayingIndex: React.Dispatch<React.SetStateAction<number | null>>;
}

const ReelCard: React.FC<ReelCardProps> = ({ url, index, playingIndex, setPlayingIndex }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const isPlaying = playingIndex === index;

  useEffect(() => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.play().catch(e => console.error("Error playing:", e));
      } else {
        videoRef.current.pause();
        videoRef.current.currentTime = 0;
      }
    }
  }, [isPlaying]);

  const togglePlay = () => {
    if (isPlaying) {
      setPlayingIndex(null);
    } else {
      setPlayingIndex(index);
    }
  };

  return (
    <div className="aspect-[9/16] relative rounded-2xl overflow-hidden glass border border-white/5 group shadow-lg">
      <video
        ref={videoRef}
        src={url}
        className="w-full h-full object-cover"
        loop
        playsInline
        controls={isPlaying} 
        preload="metadata"
      />

      {!isPlaying && (
        <div 
          className="absolute inset-0 z-10 flex items-center justify-center cursor-pointer play-overlay"
          onClick={togglePlay}
        >
          <div className="w-16 h-16 rounded-full bg-accent/90 flex items-center justify-center shadow-[0_0_30px_#DC143C] group-hover:scale-110 transition-transform">
            <Play className="text-white fill-current ml-1" size={32} />
          </div>
          <div className="absolute bottom-4 left-0 right-0 text-center">
            <span className="text-[10px] uppercase font-black tracking-widest text-white/80">Assistir</span>
          </div>
        </div>
      )}
    </div>
  );
};

// --- Helper ---
const parseDate = (dateString: string) => {
  if (!dateString) return new Date();
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
};

