  const [formVehicle, setFormVehicle] = useState('');
  const [formColor, setFormColor] = useState('');
  const [formObs, setFormObs] = useState('');

  // Fetch CMS Data and Log Visit
  useEffect(() => {
    const fetchData = async () => {
      try {
        // --- LOGIC VISIT COUNTER (30 MIN SESSION) ---
        const SESSION_KEY = 'extreme_stetica_last_visit';
        const SESSION_DURATION = 30 * 60 * 1000; // 30 minutes in milliseconds

        const now = Date.now();
        const lastVisit = localStorage.getItem(SESSION_KEY);
        let shouldCountVisit = false;

        if (!lastVisit) {
          // First time visitor or storage cleared
          shouldCountVisit = true;
        } else {
          const lastVisitTime = parseInt(lastVisit, 10);
          // If time passed since last visit is greater than 30 mins, count as new visit
          if (now - lastVisitTime > SESSION_DURATION) {
            shouldCountVisit = true;
          }
        }

        if (shouldCountVisit) {
          const analyticsRef = doc(db, "analytics", "stats");
          try {
            await updateDoc(analyticsRef, { visits: increment(1) });
          } catch (e) {
            // If doc doesn't exist yet
            await setDoc(analyticsRef, { visits: 1 }, { merge: true });
          }
        }

        // Always update the timestamp to keep the session "alive" while the user is active/refreshing
        localStorage.setItem(SESSION_KEY, now.toString());
        // ---------------------------------------------

        // Fetch Content
        const contentRef = doc(db, "site_content", "main");
        const docSnap = await getDoc(contentRef);
        if (docSnap.exists()) {
          const data = docSnap.data();
          if (data.reels) setReels(data.reels);
          if (data.products) setProducts(data.products);
          if (data.heroVideo) setHeroVideo(data.heroVideo);
          if (data.heroVideoMobile) setHeroVideoMobile(data.heroVideoMobile);
          if (data.heroOpacity !== undefined) setHeroOpacity(data.heroOpacity);
          if (data.heroBlur !== undefined) setHeroBlur(data.heroBlur);
        }
      } catch (error) {
        console.log("Using default data (offline or config issue)");
      }
    };
    fetchData();
  }, []);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 80;
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  const handleBookingSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSunday(parseDate(formDate))) {
      setToast({ message: 'Não funcionamos aos domingos. Selecione outra data.', type: 'error' });
      return;
    }
    if (!formTime || !formName || !formPhone || !formVehicle) {
